import re


def bulk_discount(qty):
    if qty >= 120:
        return 0.12
    if qty >= 30:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4})/(\d{4})/([A-Za-z])$")


def parse_sku(s):
    m = _SKU_RE.match(s) if isinstance(s, str) else None
    if not m:
        raise ValueError("invalid SKU: " + repr(s))
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

